package at.daude.Entities;

import at.daude.Physik.Hitbox;
import at.daude.Tiles.InteractiveTiles.InteractiveTile;
import at.daude.core.AppSettings;
import at.daude.core.GamePanel;
import javafx.scene.canvas.GraphicsContext;
import javafx.scene.image.Image;

import java.util.Objects;


public class Player extends Entity{
    //Interface
    GamePanel gp;

    //Position
    public final double sX;
    public final double sY;
    public int actualspeed = speed;

    public boolean controlsLocked = false;




    /**Constructor, setting Interfaces, position and hitbox
     * And applying default Values and player images */
    public Player(GamePanel gp){
        super(gp);
        this.gp = gp;

        sX = (AppSettings.desktopWidth)/2 - (double)GamePanel.tileSize / 2;
        sY = (AppSettings.desktopHeight)/2 - (double)GamePanel.tileSize / 2;
        hitBox = new Hitbox(6,42,50,16);
        hitBoxX = (int) hitBox.getX();
        hitBoxY = (int) hitBox.getY();



        setDefaultValues();
        getPlayerImages();
    }
    //Default values
    public void setDefaultValues(){
        wX = 50* GamePanel.tileSize;
        wY = 48* GamePanel.tileSize;
        speed = 8;
        hearts = 3;
        direction = "down";
    }
    //Images
    public void getPlayerImages(){
        up1 =   new Image(Objects.requireNonNull(getClass().getResourceAsStream("/Player/up1.png")));
        up2 =   new Image(Objects.requireNonNull(getClass().getResourceAsStream("/Player/up2.png")));
        down1 = new Image(Objects.requireNonNull(getClass().getResourceAsStream("/Player/down1.png")));
        down2 = new Image(Objects.requireNonNull(getClass().getResourceAsStream("/Player/down2.png")));
        right1 =new Image(Objects.requireNonNull(getClass().getResourceAsStream("/Player/right1.png")));
        right2 =new Image(Objects.requireNonNull(getClass().getResourceAsStream("/Player/right2.png")));
        left1 = new Image(Objects.requireNonNull(getClass().getResourceAsStream("/Player/left1.png")));
        left2 = new Image(Objects.requireNonNull(getClass().getResourceAsStream("/Player/left2.png")));
    }

    public void move(String direction) {
        this.direction = direction;
        int collisionId = switch (direction) {
            case "up" -> 1;
            case "down" -> 2;
            case "left" -> 3;
            case "right" -> 4;
            default -> 0;
        };
        if (contains(gp.collision.checkTile(this), collisionId)) {
            switch (direction) {
                case "up" -> wY -= actualspeed;
                case "down" -> wY += actualspeed;
                case "left" -> wX -= actualspeed;
                case "right" -> wX += actualspeed;
            }
        }
    }


    public void update(){
        actualspeed = speed + speedBuff();

        int objID = gp.collision.checkItems(this, true);
        collectItem(objID);
        gp.interactiveTileManager.touch(this);

        //Switches direction images
        eC++;
        if (eC > 10) {
            eN = eN == 1 ? 2 : 1;
            eC = 0;
        }
    }


    //Item collecting
    public void collectItem(int i){
        if(i != 404){
            boolean vanish = gp.itemManager.obj[i].interact(gp);
            if(vanish){
                gp.itemManager.obj[i]=null;
            }
        }
    }

    //Draw
    public void draw(GraphicsContext gc){
        Image image = null;

        //Animation image switch
        switch (direction) {
            case "up" -> image = (eN == 1 ? up1 : up2);
            case "down" -> image = (eN == 1 ? down1 : down2);
            case "left" -> image = (eN == 1 ? left1 : left2);
            case "right" -> image = (eN == 1 ? right1 : right2);
        }
        gc.drawImage(image, sX,sY, GamePanel.tileSize, GamePanel.tileSize);
    }

}

